const body = $input.first().json.body || $input.first().json;
// n8n puts the POST body under .body; fall back to the item itself when testing.

const grid = body.grid || {};
const schema = Array.isArray(body.schema) ? body.schema : [];
if (!Array.isArray(grid.cells) || grid.cells.length === 0) throw new Error('grid.cells must contain at least one cell');
if (schema.length === 0) throw new Error('schema must contain at least one tag');
// The logged-in user's details are NOT sent to the model: the backend fills account-manager tags itself (see "userSource").

const prompt = [
  'REF_NO: ' + (body.refNo || ''),
  'TODAY: ' + (body.today || ''),
  'ROW FLAG KEY: "' + (body.groupFlag || '_group') + '" - on every heading row and every total / sub-total row of a loop, add this key to that row object as the JSON boolean true (e.g. {"item": "Total", ..., "' + (body.groupFlag || '_group') + '": true}). Do not add it to other rows.',
  '',
  'TAG SCHEMA (the tags of the Word template you must fill; "context" is the template text around the tag, children = the fields of a loop):',
  JSON.stringify(schema),
  '',
  'SHEET "' + (grid.sheetName || '') + '" - MERGED RANGES (the content of a merged range is in its top-left cell):',
  JSON.stringify((grid.merges || []).map(function (m) { return m.range; })),
  '',
  'SHEET CELLS - every non-empty cell as {a: address, v: value[, t: displayed text]}; t = what the sheet displays when it differs from v:',
  JSON.stringify(grid.cells.map(function (c) { var o = { a: c.address, v: c.value }; if (c.text) o.t = c.text; return o; }))
].join('\n');

return [{ json: { prompt: prompt, schema: schema } }];

const input = $('Webhook').first().json;
const request = input.body || input; // what the backend sent (refNo when already fixed, else refRequest)
const schema = $('Build Prompt').first().json.schema || [];
// Only tag names from the schema are ever returned; the backend checks the answer again.

// The VALUE of the quotation reference, safe to use as the end of the reference number: label prefixes ("PR:", "PR -", "Ref:",
// "Ref No:", "Quotation No:", "Quote #") removed, slashes / spaces -> "-", every character except letters, digits, ".", "_", "-" dropped.
// "" when nothing usable is left (e.g. the AI returned only the label "PR:").
function cleanQuotationRef(raw) {
  var v = String(raw == null ? '' : raw).trim();
  var label = /^\s*(?:(?:quotation|quote|proposal|reference|ref|pr)\b\s*(?:no\.?|number|num\.?|#)?\s*[:#\-.]*\s*)+/i;
  for (var i = 0; i < 4; i++) { var next = v.replace(label, ''); if (next === v) break; v = next; }
  v = v.replace(/^[\s:#.\-]+/, '');
  return v.replace(/[\s\/\\]+/g, '-').replace(/[^A-Za-z0-9._-]/g, '').replace(/-{2,}/g, '-').replace(/^[-._]+|[-._]+$/g, '');
}

let raw = String($input.first().json.output || '').trim();
raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsed = null;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start !== -1 && end > start) {
    try { parsed = JSON.parse(raw.substring(start, end + 1)); } catch (e2) { parsed = null; }
  }
}

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  return [{ json: { error: 'invalid_ai_output', raw: raw.substring(0, 20000) } }];
}

const values = (parsed.values && typeof parsed.values === 'object' && !Array.isArray(parsed.values)) ? parsed.values : {};
const names = schema.map(function (t) { return t.name; });
const missing = Array.isArray(parsed.missing) ? parsed.missing.filter(function (n) { return names.indexOf(n) !== -1; }) : [];
const meta = (parsed.meta && typeof parsed.meta === 'object') ? parsed.meta : {};
const userFields = ['name', 'phone', 'email', 'designation', 'division'];
const userSource = Array.isArray(parsed.userSource) ? parsed.userSource.filter(function (u) {
  return u && names.indexOf(u.tag) !== -1 && userFields.indexOf(u.field) !== -1;
}).map(function (u) { return { tag: u.tag, field: u.field }; }) : [];

// Reference number: a fixed one (Regenerate) is echoed back. Otherwise it is SLTM-<section>-<sub-section>-<quotationRef>, or "" when the
// section, sub-section or the cleaned quotation reference is missing - never a partial reference, never the raw value from the Excel.
const quotationRef = cleanQuotationRef(parsed.quotationRef);
let refNo = '';
if (request.refNo) {
  refNo = String(request.refNo).trim();
} else if (request.refRequest && quotationRef) {
  const norm = function (v) { return String(v || '').toUpperCase().replace(/[^A-Z0-9]/g, ''); };
  const section = norm(request.refRequest.section);
  const sub = norm(request.refRequest.subSection);
  if (section && sub) refNo = 'SLTM-' + section + '-' + sub + '-' + quotationRef;
  if (!/^SLTM-[A-Z0-9]+-[A-Z0-9]+-[A-Za-z0-9._-]+$/.test(refNo)) refNo = '';
}

return [{ json: { values: values, missing: missing, userSource: userSource, quotationRef: quotationRef, refNo: refNo, meta: { customerName: typeof meta.customerName === 'string' ? meta.customerName : '' } } }];
